import Vue from 'vue'
import VueRouter from 'vue-router'

Vue.use(VueRouter)

const routes = [
  {
    path: '/login',
    name: 'Login',
    component: () => import('../views/auth/LoginView.vue')
  },
  {
    path: '/register',
    name: 'Register',
    component: () => import('../views/auth/RegisterView.vue')
  },
  {
    path: '/',
    component: () => import('../views/LayoutView.vue'),
    redirect: '/dashboard',
    children: [
      {
        path: 'dashboard',
        name: 'Dashboard',
        component: () => import('../views/dashboard/DashboardView.vue'),
        meta: { title: '数据看板' }
      },
      {
        path: 'bim',
        name: 'BimModel',
        component: () => import('../views/bim/BimModelView.vue'),
        meta: { title: 'BIM模型' }
      },
      {
        path: 'maintenance',
        name: 'MaintenanceList',
        component: () => import('../views/maintenance/MaintenanceListView.vue'),
        meta: { title: '维修记录' }
      },
      {
        path: 'maintenance/create',
        name: 'MaintenanceCreate',
        component: () => import('../views/maintenance/MaintenanceFormView.vue'),
        meta: { title: '新建报修' }
      },
      {
        path: 'maintenance/edit/:id',
        name: 'MaintenanceEdit',
        component: () => import('../views/maintenance/MaintenanceFormView.vue'),
        meta: { title: '编辑报修' }
      },
      {
        path: 'maintenance/detail/:id',
        name: 'MaintenanceDetail',
        component: () => import('../views/maintenance/MaintenanceDetailView.vue'),
        meta: { title: '维修详情' }
      },
      {
        path: 'users',
        name: 'UserManage',
        component: () => import('../views/auth/UserManageView.vue'),
        meta: { title: '用户管理', requiresAdmin: true }
      }
    ]
  }
]

const router = new VueRouter({
  mode: 'history',
  routes
})

// 全局路由守卫：未登录时跳转到登录页
router.beforeEach((to, from, next) => {
  const token = localStorage.getItem('token')
  if (to.path !== '/login' && to.path !== '/register' && !token) {
    next('/login')
  } else {
    next()
  }
})

export default router
